{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례상 불을 붙이지 않고 종이담배를 손에만 들고 있는 상태를 흡연으로 보는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "해당 조례 제2조제2호는 \"흡연\"을 담배를 피우는 행위뿐 아니라 불이 붙은 담배를 소지하는 것까지 포함한다고 정의한다. 질문의 상태는 불을 붙이지 않았으므로 \"불이 붙은 담배\"에 해당하지 않아, 이 정의만으로는 흡연으로 보지 않는다. 다만 \"담배를 피우는 행위\"에 해당하는지는 별도로 판단해야 한다.",
          "b_ids": "금연:제2조제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
